const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Find all occurrences of 'coffee' (case-insensitive)
let idx = 0;
const lower = text.toLowerCase();
while (true) {
  idx = lower.indexOf('coffee', idx);
  if (idx === -1) break;
  const start = Math.max(0, idx - 300);
  const end = Math.min(buf.length, idx + 300);
  console.log('=== Found at offset', idx, '===');
  console.log(buf.toString('utf8', start, end).replace(/[\x00-\x1f]/g, ' '));
  console.log();
  idx++;
}
"
